# -*- coding: utf-8 -*-
"""КОЛІР-Р2 (рядок 2693): живий суд (`pipeline.перевірити_від_моделі`) на образах 4 сцен стенда — ті самі 40 випадкових
(сід 7, як `колір_опори_до_після.py`) і до 6 на сцену «гучна сукня/верх × гучний аксесуар одного слова кольору»
(як `колір_відлуння_образи.py`), і 9 на сцену з усього каталогу «гучна сукня/верх × гучний аксесуар чи взуття», обидва — вимір, ≤45° CIELAB:
6 — 15–45° кола художника (сусідні сектори — пари, чий вердикт відлуння КОЛІР-Р2 міняє), 3 — ≤15° (контроль). Друкує лічбу знахідок правил повтору кольору (K-COL-05 сирота, K-CRA-02 фокуси,
K-COL-02 бюджет, K-COMP-03 сім'ї, K-PAL-15; гучність речі — K-PAL-05/06/12/18, R-COL-16, K-ACC-10, КОЛІР-Р4-2б) і опор K-ACC-01, а з `-д` — підпис кожного образу (для diff ДО/ПІСЛЯ): назва,
слово кольору («~» — колір-вікно слова, не вимір), hex.
Запуск із джерела/: python3 проби/колір_відлуння_суд.py [-д]"""
import json, random, sys, collections as K; sys.path.insert(0, ".")
import bridge as B, fit as ПС, colorspace as cs, pipeline as PL, стенд_знімок as СЗ, аксесуари_структура as АС, palettes as PS, колір_річ as КР
вх0 = json.load(open("стенд_вх.json", encoding="utf-8"))
T = ПС.тіло(float(вх0["зріст"]), {k: float(v) for k, v in вх0["обхвати"].items()}); F = cs.features(cs.hx(вх0["шкіра"]), cs.hx(вх0["волосся"][0]), cs.hx(вх0["очі"]))
ПР = ("K-COL-05", "K-CRA-02", "K-COL-02", "K-COMP-03", "K-PAL-15", "K-ACC-01", "K-COMP-05", "K-PAL-05", "K-PAL-06", "K-PAL-12", "K-PAL-18", "R-COL-16", "K-ACC-10")
СЛОТИ = ("верх", "низ", "сукня", "верхній_шар", "взуття", "сумка", "шарф", "сережки", "намисто"); Л = K.Counter(); Д = []
гучна = lambda x: (АС._C_речі(x) or 0.0) >= 40
for назва in ("офіс·18°C", "дощ·ресторан·вечір", "весілля·гість", "спека·парк"):
    сц = dict(СЗ.СЦЕНАРІЇ[назва])
    к = json.loads(B.виклик("запити", json.dumps(dict(вх0, сценарій=сц, випадок=назва), ensure_ascii=False)))["кандидати"]
    кат = B.каталог_останнього_пакета(); зі = {r["id"]: r for r in кат}; rnd = random.Random(7); образи = []
    for n in range(10):
        образи.append([rnd.choice(к[с])["id"] for с in СЛОТИ if к.get(с) and с not in (("верх", "низ") if n % 2 == 0 else ("сукня",))])
    вел = [r["id"] for с in ("сукня", "верх") for r in к.get(с, []) if гучна(зі.get(r["id"]) or {})]
    акс = [r["id"] for с in АС.СЛОТИ_АКСЕСУАРІВ for r in к.get(с, []) if гучна(зі.get(r["id"]) or {})]
    for a, b in [(a, b) for a in вел for b in акс if зі[a].get("колір_ім") and зі[a].get("колір_ім") == зі[b].get("колір_ім")][:6]:
        образи.append([a, b] + ([к["низ"][0]["id"]] if зі[a].get("слот") == "верх" and к.get("низ") else []) + ([к["взуття"][0]["id"]] if к.get("взуття") else []))
    вим = lambda с: [r["id"] for r in кат if r.get("слот") in с and гучна(r) and not КР.не_вимір(r)]   # увесь каталог руки 1
    h = lambda x: cs.lch(tuple(зі[x]["lab"]))[2]
    пари = [(a, b, КР.кут_на_колі(h(a), h(b))) for a in вим(("сукня", "верх")) for b in вим(АС.СЛОТИ_АКСЕСУАРІВ + ("взуття",)) if КР._кут(h(a), h(b)) <= 45]
    for a, b, _ in rnd.sample([п for п in пари if 15 < п[2] <= 45], 6) + rnd.sample([п for п in пари if п[2] <= 15], 3):
        образи.append([a, b] + ([к["низ"][0]["id"]] if зі[a].get("слот") == "верх" and к.get("низ") else []) + ([к["взуття"][0]["id"]] if к.get("взуття") and зі[b].get("слот") != "взуття" else []))
    for i, ід in enumerate(образи):
        в = PL.перевірити_від_моделі(ід, F, кат, T, сценарій=dict(сц), кандидати=к)
        зн = sorted("%s:%s" % (z.get("правило"), z.get("сила")) for z in в.get("знахідки") or [] if z.get("правило") in ПР)
        оп = sorted("опора:%s" % o.get("правило") for o in в.get("опори") or [] if o.get("правило") in ПР)
        for x in зн + оп: Л[x] += 1
        Л["образів"] += 1
        Д.append("%s#%02d %s | %s" % (назва[:6], i, " ".join(зн + оп), " · ".join("%s %s%s %s" % ((зі[x].get("назва") or "")[:26], зі[x].get("колір_ім") or "", "~" if КР.не_вимір(зі[x]) else "", PS._hex(зі[x]["lab"]) if зі[x].get("lab") else "—") for x in ід)))
for к_, v in sorted(Л.items()): print("  %-28s %4d" % (к_, v))
if "-д" in sys.argv: print("\n".join(Д))
